import React, { useState } from 'react';
import { Link } from 'react-router-dom'; // do nawigacji w PWA
import ItemAdd from './ItemAdd';

interface ItemListProps {
  username: string;
  avatar: string;
  onLogout: () => void;
}

const ItemList: React.FC<ItemListProps> = ({ username, avatar, onLogout }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [showAddItem, setShowAddItem] = useState(false);
  const [activeMenu2, setActiveMenu2] = useState<number>(1);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    if (window.confirm("Czy na pewno chcesz się wylogować?")) {
      onLogout();
    }
  };

  const navigateToAddItem = () => {
    setShowAddItem(true);
    setIsMenuOpen(false);
  };

  const navigateToList = () => {
    setShowAddItem(false);
  };

  if (showAddItem) {
    return (
      <ItemAdd 
        username={username} 
        avatar={avatar} 
        onLogout={onLogout} 
        onNavigateToList={navigateToList} 
      />
    );
  }

  return (
    <div className="container">
      <div className="menu">
        <button onClick={toggleMenu}>Menu</button>
        <img src="./assets/skinradar.png" alt="logo" className="logo" />
        <button onClick={toggleUserMenu}>
          <img src={avatar} alt="avatar" className="avatar" />
        </button>
      </div>

      {isMenuOpen && (
        <div className="dropdownMenu">
          <Link to="/" className="dropdownButton">LISTA</Link>
          <button onClick={navigateToAddItem} className="dropdownButton">DODAJ</button>
        </div>
      )}

      {isUserMenuOpen && (
        <div className="userMenu">
          <p className="userMenuText">{username}</p>
          <button onClick={handleLogout} className="logoutButton">
            <img src="./assets/logout.png" alt="logout" className="logoutIcon" />
          </button>
        </div>
      )}

      <div className="content">
        <h1>Witaj w aplikacji SkinRadar!</h1>
      </div>

      <div className="menu2">
        {[
          './assets/settings.png',
          './assets/bell.png',
          './assets/questmark.png',
        ].map((icon, idx) => (
          <button key={idx} onClick={() => setActiveMenu2(idx)} className="menu2Button">
            <div className={activeMenu2 === idx ? "menu2IconWrapper active" : "menu2IconWrapper"}>
              <img src={icon} alt="icon" className={activeMenu2 === idx ? "menuButtonIcon active" : "menuButtonIcon"} />
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

export default ItemList;
